### Implement Unreal Bloom postprocessing pass in Three.js

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_postprocessing_unreal_bloom.html

Sets up a Three.js scene with GLTF animation, tone mapping, EffectComposer, and UnrealBloomPass with configurable threshold, strength, and radius controls.

```javascript
import * as THREE from 'three'; import Stats from 'three/addons/libs/stats.module.js'; import { GUI } from 'three/addons/libs/lil-gui.module.min.js'; import { OrbitControls } from 'three/addons/controls/OrbitControls.js'; import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js'; import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js'; import { RenderPass } from 'three/addons/postprocessing/RenderPass.js'; import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js'; import { OutputPass } from 'three/addons/postprocessing/OutputPass.js'; let camera, stats; let composer, renderer, mixer, timer; const params = { threshold: 0, strength: 1, radius: 0.5, exposure: 1 }; init(); async function init() { const container = document.getElementById( 'container' ); timer = new THREE.Timer(); timer.connect( document ); const scene = new THREE.Scene(); camera = new THREE.PerspectiveCamera( 40, window.innerWidth / window.innerHeight, 1, 100 ); camera.position.set( - 5, 2.5, - 3.5 ); scene.add( camera ); scene.add( new THREE.AmbientLight( 0xcccccc ) ); const pointLight = new THREE.PointLight( 0xffffff, 100 ); camera.add( pointLight ); const loader = new GLTFLoader(); const gltf = await loader.loadAsync( 'models/gltf/PrimaryIonDrive.glb' ); const model = gltf.scene; scene.add( model ); mixer = new THREE.AnimationMixer( model ); const clip = gltf.animations[ 0 ]; mixer.clipAction( clip.optimize() ).play(); // renderer = new THREE.WebGLRenderer( { antialias: true } ); renderer.setPixelRatio( window.devicePixelRatio ); renderer.setSize( window.innerWidth, window.innerHeight ); renderer.setAnimationLoop( animate ); renderer.toneMapping = THREE.ACESFilmicToneMapping; container.appendChild( renderer.domElement ); // const renderScene = new RenderPass( scene, camera ); const bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 ); bloomPass.threshold = params.threshold; bloomPass.strength = params.strength; bloomPass.radius = params.radius; const outputPass = new OutputPass(); composer = new EffectComposer( renderer ); composer.addPass( renderScene ); composer.addPass( bloomPass ); composer.addPass( outputPass ); // stats = new Stats(); container.appendChild( stats.dom ); // const controls = new OrbitControls( camera, renderer.domElement ); controls.maxPolarAngle = Math.PI * 0.5; controls.minDistance = 3; controls.maxDistance = 8; // const gui = new GUI(); const bloomFolder = gui.addFolder( 'bloom' ); bloomFolder.add( params, 'threshold', 0.0, 1.0 ).onChange( function ( value ) { bloomPass.threshold = Number( value ); } ); bloomFolder.add( params, 'strength', 0.0, 3.0 ).onChange( function ( value ) { bloomPass.strength = Number( value ); } ); gui.add( params, 'radius', 0.0, 1.0 ).step( 0.01 ).onChange( function ( value ) { bloomPass.radius = Number( value ); } ); const toneMappingFolder = gui.addFolder( 'tone mapping' ); toneMappingFolder.add( params, 'exposure', 0.1, 2 ).onChange( function ( value ) { renderer.toneMappingExposure = Math.pow( value, 4.0 ); } ); window.addEventListener( 'resize', onWindowResize ); } function onWindowResize() { const width = window.innerWidth; const height = window.innerHeight; camera.aspect = width / height; camera.updateProjectionMatrix(); renderer.setSize( width, height ); composer.setSize( width, height ); } function animate() { timer.update(); const delta = timer.getDelta(); mixer.update( delta ); stats.update(); composer.render(); }
```

--------------------------------

### WebGLRenderer with ACES tone mapping and EffectComposer/RenderPass/UnrealBloomPass

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_postprocessing_unreal_bloom.html

Configures WebGLRenderer with ACESFilmicToneMapping (sRGB output by default), then sets up EffectComposer with RenderPass, UnrealBloomPass, and OutputPass for correct color space handling.

```javascript
renderer = new THREE.WebGLRenderer( { antialias: true } );
renderer.setPixelRatio( window.devicePixelRatio );
renderer.setSize( window.innerWidth, window.innerHeight );
renderer.setAnimationLoop( animate );
renderer.toneMapping = THREE.ACESFilmicToneMapping;

const renderScene = new RenderPass( scene, camera );

const bloomPass = new UnrealBloomPass( new THREE.Vector2( window.innerWidth, window.innerHeight ), 1.5, 0.4, 0.85 );
bloomPass.threshold = params.threshold;
bloomPass.strength = params.strength;
bloomPass.radius = params.radius;

const outputPass = new OutputPass();

composer = new EffectComposer( renderer );
composer.addPass( renderScene );
composer.addPass( bloomPass );
composer.addPass( outputPass );
```

--------------------------------

### MeshStandardMaterial shader chunk ordering template

Source: https://github.com/mrdoob/three.js/blob/dev/src/renderers/shaders/ShaderLib/meshphysical.glsl.js

The complete vertex and fragment shader template for MeshStandardMaterial/MeshPhysicalMaterial. This is the `#include` chunk ordering that `onBeforeCompile` receives in `parameters.vertexShader`/`parameters.fragmentShader` after chunk resolution, serving as the base template for custom injection.

```javascript
export const vertex = /* glsl */`
#define STANDARD

