1, 2, 1 ); dummy.updateMatrix(); color.setHSL( 1, 0.5 + ( Math.random() \* 0.5 ), 0.5 + ( Math.random() \* 0.5 ) ); baseColors.push( color.getHex() ); mesh.setMatrixAt( i, dummy.matrix ); mesh.setColorAt( i, color.multiply( colors\[ 0 \] ) ); i ++; seeds.push( Math.random() ); } } // window.addEventListener( 'resize', onWindowResize ); setInterval( startTween, 3000 ); } function startTween() { // tween for animating color transition new TWEEN.Tween( animation ) .to( { t: 1 }, 2000 ) .easing( TWEEN.Easing.Sinusoidal.In ) .onComplete( () => { animation.t = 0; currentColorIndex = nextColorIndex; nextColorIndex ++; if ( nextColorIndex >= colors.length ) nextColorIndex = 0; } ) .start(); } function onWindowResize() { camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize( window.innerWidth, window.innerHeight ); } // function animate() { timer.update(); const time = timer.getElapsed(); TWEEN.update(); // animate camera camera.position.x = Math.sin( time / 4 ) \* 10; camera.position.z = Math.cos( time / 4 ) \* 10; camera.position.y = 8 + Math.cos( time / 2 ) \* 2; cameraTarget.x = Math.sin( time / 4 ) \* - 8; cameraTarget.z = Math.cos( time / 2 ) \* - 8; camera.lookAt( cameraTarget ); camera.up.x = Math.sin( time / 400 ); // animate instance positions and colors for ( let i = 0; i < mesh.count; i ++ ) { mesh.getMatrixAt( i, dummy.matrix ); dummy.matrix.decompose( dummy.position, dummy.quaternion, dummy.scale ); dummy.position.y = Math.abs( Math.sin( ( time + seeds\[ i \] ) \* 2 + seeds\[ i \] ) ); dummy.updateMatrix(); mesh.setMatrixAt( i, dummy.matrix ); // colors if ( animation.t > 0 ) { const currentColor = colors\[ currentColorIndex \]; const nextColor = colors\[ nextColorIndex \]; const f = dummy.position.length() / maxDistance; if ( f <= animation.t ) { color.set( baseColors\[ i \] ).multiply( nextColor ); } else { color.set( baseColors\[ i \] ).multiply( currentColor ); } mesh.setColorAt( i, color ); } } mesh.instanceMatrix.needsUpdate = true; if ( animation.t > 0 ) mesh.instanceColor.needsUpdate = true; mesh.computeBoundingSphere(); renderer.render( scene, camera ); }
```

--------------------------------

### Recompute InstancedMesh Bounding Volumes

Source: https://github.com/mrdoob/three.js/blob/dev/manual/pages/how-to-update-things.html

Call computeBoundingBox and computeBoundingSphere whenever instance transforms change via setMatrixAt. These properties ensure features like view frustum culling and ray casting function correctly.

```javascript
instancedMesh.computeBoundingBox();
instancedMesh.computeBoundingSphere();
```

--------------------------------

### Disposing geometries, materials, textures and meshes

Source: https://github.com/mrdoob/three.js/blob/dev/manual/examples/cleanup-simple.html

Official pattern (from the 'Cleanup' manual article) for freeing WebGL resources. A ResourceTracker class lets you wrap every geometry, material, texture, and Mesh you create with track(), and calling dispose() removes tracked Object3D nodes from their parent and calls dispose() on each resource so geometries/materials/textures release their GL buffers and shader programs.

```javascript
	class ResourceTracker {

		constructor() {

			this.resources = new Set();

		}
		track( resource ) {

			if ( resource.dispose || resource instanceof THREE.Object3D ) {

				this.resources.add( resource );

			}

			return resource;

		}
		untrack( resource ) {

			this.resources.delete( resource );

		}
		dispose() {

			for ( const resource of this.resources ) {

				if ( resource instanceof THREE.Object3D ) {

					if ( resource.parent ) {

						resource.parent.remove( resource );

					}

				}

				if ( resource.dispose ) {

					resource.dispose();

				}

			}

			this.resources.clear();

		}

	}

	function addStuffToScene() {

		const resTracker = new ResourceTracker();
		const track = resTracker.track.bind( resTracker );

		const boxWidth = 1;
		const boxHeight = 1;
		const boxDepth = 1;
		const geometry = track( new THREE.BoxGeometry( boxWidth, boxHeight, boxDepth ) );

		const loader = new THREE.TextureLoader();
		const texture = loader.load( 'resources/images/wall.jpg' );
		texture.colorSpace = THREE.SRGBColorSpace;

		const material = track( new THREE.MeshBasicMaterial( {
			map: track( texture ),
		} ) );
		const cube = track( new THREE.Mesh( geometry, material ) );
		scene.add( cube );
		cubes.push( cube ); // add to our list of cubes to rotate
		return resTracker;

	}
```

### Methods > .dispose()

Source: https://github.com/mrdoob/three.js/blob/dev/docs/pages/Object3D.html.md

Frees the GPU-related resources allocated by this instance. Call this method whenever this instance is no longer used in your app.

Geometries, materials and textures are potentially shared with other 3D objects and must be disposed of separately.

##### Fires:

*   [Object3D#event:dispose](Object3D.html#event:dispose)

