export function sweepAABB(a, b, ax, ay, bx, by, out) {
  const px = a.x - b.x, py = a.y - b.y;
  const dx = ax - bx, dy = ay - by;
  const hx = a.hx + b.hx, hy = a.hy + b.hy;
