import { CONFIG, PHASE, EVENT } from './config.js';
import { Gameplay } from './Gameplay.js';
import { World } from './World.js';
import { HUD } from './HUD.js';
import { GameLoop } from '../shared/core/GameLoop.js';
import { InputController } from '../shared/core/InputController.js';
import { ResourceScope } from '../shared/core/ResourceScope.js';
import { clamp } from '../shared/core/math.js';
import { RenderPipeline } from '../shared/rendering/RenderPipeline.js';
import { EffectsManager } from '../shared/vfx/EffectsManager.js';
import { AudioSystem } from '../shared/audio/AudioSystem.js';
const STORAGE='neon-siege:v1';
const FX_DEFAULT={x:0,y:0,vx:0,vy:0,count:0,palette:0,priority:0,trauma:0,freeze:0,rings:0,score:0,radius:.12,life:.4,speed:3};
const ALIEN_PALETTES=[1,2,3];
export class Game {
  constructor({mount}){
    this.mount=mount;this.scope=new ResourceScope();this.disposed=false;this.paused=false;this.settingsOpen=false;this.contextLost=false;this.presentationTime=0;this.hudTimer=0;this.lastPhase='';this.resizePending=true;this.exhaustTimer=0;
    this.params=new URLSearchParams(location.search);this.best=0;
    this.settings={music:.25,sfx:.5,quality:'balanced',shake:true,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,touch:matchMedia('(pointer: coarse)').matches,muted:false};
    this.loadSettings();this.fxSpec={...FX_DEFAULT};this.audioParams={x:0,priority:1,note:0};this.musicParams={tempo:100,section:0,tension:0,playing:false,saucer:false};
    this.fxFrame={dt:0,simulated:0,paused:false,reduced:false,shake:true,sources:null};
    this.view={state:null,settings:this.settings,best:this.best,paused:false,settingsOpen:false,remaining:55,device:'keyboard'};
    this.handleAction=this.handleAction.bind(this);this.handleEvent=this.handleEvent.bind(this);
  }
  loadSettings(){
    try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(!saved)return;
      if(Number.isFinite(saved.best)&&saved.best>=0)this.best=Math.min(999999999,Math.floor(saved.best));
      const s=saved.settings;if(!s||typeof s!=='object')return;
      for(const key of ['music','sfx'])if(Number.isFinite(s[key]))this.settings[key]=clamp(s[key],0,1);
      for(const key of ['shake','reduced','touch','muted'])if(typeof s[key]==='boolean')this.settings[key]=s[key];
      if(['high','balanced','low'].includes(s.quality))this.settings.quality=s.quality;
    }catch{ /* Storage is optional; defaults remain usable. */ }
  }
  persist(){try{localStorage.setItem(STORAGE,JSON.stringify({best:this.best,settings:this.settings}));}catch{ /* Private/storage-disabled browsers can still play. */ }}
  initialize(){
    this.input=new InputController();this.audio=new AudioSystem(128);
    this.hud=new HUD({mount:this.mount,onAction:this.handleAction,onVirtualInput:(...args)=>this.input.setVirtual(...args)});
    this.pipeline=new RenderPipeline({mount:this.hud.stage,onContextLost:()=>{this.contextLost=true;this.pause();},onContextRestored:()=>{
      if(this.disposed)return;this.world.rebuildEnvironment(this.pipeline.renderer);this.pipeline.rebuild();this.world.sync(this.gameplay,1,this.presentationTime);this.pipeline.warmup();this.contextLost=false;this.paused=true;this.resizePending=true;
    },onError:error=>this.fail(error)});
    this.world=new World({renderer:this.pipeline.renderer,config:CONFIG,seed:128});this.pipeline.setScene(this.world.scene,this.world.camera);
    this.gameplay=new Gameplay({seed:1});this.view.state=this.gameplay.state;
    this.effects=new EffectsManager({scene:this.world.scene,camera:this.world.camera,labelRoot:this.hud.labelRoot,impactLights:this.world.impactLights,seed:787,budgets:CONFIG.budgets});this.fxFrame.sources=this.world.trailSources;
    this.loop=new GameLoop({fixedDt:1/120,maxSteps:8,beforeFrame:dt=>this.beforeFrame(dt),fixedUpdate:h=>{this.gameplay.step(h,this.actions);this.gameplay.events.drain(this.handleEvent);this.effects.flush();},render:(alpha,dt,simulated)=>this.render(alpha,dt,simulated),getSimulationDelta:dt=>this.paused||this.contextLost?0:this.effects.hitStop.consume(dt),shouldHaltSteps:()=>this.paused||this.effects.hitStop.active});
    const observe=new ResizeObserver(()=>{this.resizePending=true;});observe.observe(this.hud.stage);this.scope.defer(()=>observe.disconnect());
    const blur=()=>{if(this.activePhase())this.pause();};const visibility=()=>{if(document.hidden&&this.activePhase())this.pause();};
    const error=e=>this.fail(e.error||new Error(e.message||'Unexpected runtime error'));
    for(const [target,name,fn]of [[window,'blur',blur],[document,'visibilitychange',visibility],[window,'error',error]]){target.addEventListener(name,fn);this.scope.defer(()=>target.removeEventListener(name,fn));}
    if(this.params.has('debug')){window.__SPACE_INVADERS__=Object.freeze({snapshot:()=>this.getDiagnostics()});this.scope.defer(()=>delete window.__SPACE_INVADERS__);}
    this.applySettings();this.resize();this.actions=this.input.sample();this.world.sync(this.gameplay,1,0);this.refreshHUD();this.pipeline.warmup();
    this.mount.querySelector('#startup-status')?.remove();this.loop.start();
  }
  activePhase(){const phase=this.gameplay?.state.phase;return !!phase&&phase!==PHASE.TITLE&&phase!==PHASE.VICTORY&&phase!==PHASE.GAME_OVER;}
  pause(){if(!this.gameplay)return;this.paused=true;this.input.clear();this.effects?.hitStop.clear();this.loop?.resetTime();this.audio?.setPaused(true);this.refreshHUD();}
  handleAction(action,data){
    if(this.disposed)return;
    if(action==='start'){
      const seed=this.params.has('seed')?Number(this.params.get('seed'))>>>0:crypto.getRandomValues(new Uint32Array(1))[0];
      this.paused=false;this.settingsOpen=false;this.effects.reset();this.audio.reset();this.gameplay.reset(seed);this.input.requireRelease();this.loop.resetTime();this.gameplay.events.drain(this.handleEvent);this.effects.flush();this.audio.setPaused(false);this.unlockAudio();
    }else if(action==='pause'){
      if(this.gameplay.state.phase===PHASE.TITLE){this.settingsOpen=true;this.input.requireRelease();}
      else if(this.activePhase()){if(this.paused)this.handleAction('resume');else this.pause();}
    }else if(action==='resume'){
      if(this.contextLost||document.hidden)return;this.paused=false;this.settingsOpen=false;this.input.requireRelease();this.loop.resetTime();this.audio.setPaused(false);this.unlockAudio();
    }else if(action==='settings'){
