    }else if(action==='setting'){
      if(data.key==='music'||data.key==='sfx')this.settings[data.key]=clamp(Number(data.value),0,1);
      else if(data.key==='quality'&&['high','balanced','low'].includes(data.value))this.settings.quality=data.value;
