      this.applySettings();this.persist();
    }else if(action==='reload'){location.reload();return;}
    this.refreshHUD();
  }
  unlockAudio(){this.audio.unlock().then(ready=>{if(this.disposed)return;const b=this.hud.root.querySelector('[data-action="audio"]');b.textContent=this.settings.muted?'♪':'♫';b.setAttribute('aria-label',!ready?'Enable audio':this.settings.muted?'Unmute audio':'Mute audio');b.title=!ready?'Click to enable audio':this.settings.muted?'Audio muted':'Audio enabled';});}
  applySettings(){this.audio?.setVolumes(this.settings.muted?0:this.settings.music,this.settings.muted?0:this.settings.sfx);this.resizePending=true;}
  beforeFrame(dt){
    this.actions=this.input.sample(dt);
