  resize(){if(!this.pipeline||!this.effects)return;this.resizePending=false;const rect=this.hud.stage.getBoundingClientRect();this.pipeline.resize(rect.width,rect.height,this.settings.quality);this.effects.resize(rect);}
  handleEvent(e){
    const p=this.fxSpec;Object.assign(p,FX_DEFAULT);p.x=e.x;p.y=e.y;p.vx=e.vx;p.vy=e.vy;
