    else if(e.type===EVENT.BUNKER){p.count=5;p.palette=3;p.priority=1;p.trauma=.015*impact;cue='chip';}
    else if(e.type===EVENT.INTERCEPT){p.count=6;p.palette=0;p.priority=1;p.trauma=.03;cue='chip';}
    else if(e.type===EVENT.SHIELD){p.count=6;p.palette=0;p.priority=1;p.trauma=.04;p.rings=1;p.speed=2;cue='chip';}
    else if(e.type===EVENT.DAMAGE){p.count=90;p.palette=0;p.priority=3;p.trauma=.48+.22*impact;p.freeze=.08;p.rings=2;p.life=.65;p.speed=6;cue='heavy';sound.priority=3;}
    else if(e.type===EVENT.SAUCER){p.count=48;p.palette=2;p.priority=2;p.trauma=.3;p.freeze=.05;p.rings=1;p.score=e.value;p.speed=5;p.life=.55;cue='heavy';sound.priority=2;}
