  const out={};assert.equal(sweepAABB(box(0,-5),box(0,0),0,10,0,0,out),true);assert.equal(out.time,.4);assert.equal(out.ny,-1);
  assert.equal(sweepAABB(box(2,-5),box(0,0),0,10,0,0,out),false);
  assert.equal(sweepAABB(box(1,-5),box(0,0),0,10,0,0,out),true);
  assert.equal(sweepAABB(box(-5,0),box(5,0),6,0,-6,0,out),true);assert.equal(out.time,.75);
  assert.equal(sweepAABB(box(0,0),box(0,0),0,0,0,0,out),true);assert.equal(out.time,0);assert.ok(Number.isFinite(out.nx));
  assert.equal(overlapsAABB(box(0,0),box(1,0)),true);
});
test('pool churn does not allocate records or accept stale generations',()=>{
  let factories=0;const pool=new ObjectPool(7,id=>{factories++;return {id};});const original=pool.items.slice();
  for(let round=0;round<1000;round++){
    const ids=[];for(let i=0;i<7;i++)ids.push(pool.acquire());assert.equal(pool.acquire(),-1);
    const id=ids[3],generation=pool.generations[id];assert.equal(pool.release(id,generation),true);assert.equal(pool.release(id,generation),false);
    assert.equal(pool.acquire(),id);assert.equal(pool.release(id,generation),false);pool.clear();assert.equal(pool.activeCount+pool.freeCount,7);
  }
  assert.equal(factories,7);for(let i=0;i<7;i++)assert.equal(pool.items[i],original[i]);
});
