  let disposed=0;const resource={dispose(){disposed++;}},scope=new ResourceScope();scope.own(resource);scope.own(resource);scope.disposeOwned(resource);assert.equal(scope.order.length,0);scope.dispose();scope.dispose();assert.equal(disposed,1);
});
test('random generator and hit-stop are deterministic and bounded',()=>{
  const a=new SeededRandom(0),b=new SeededRandom(0);for(let i=0;i<1000;i++)assert.equal(a.next(),b.next());
  const h=new HitStop();h.request(.04,1);h.request(.06,1);assert.equal(h.remaining,.06);h.request(.1,0);assert.equal(h.remaining,.06);
  assert.equal(h.consume(.03),0);assert.ok(Math.abs(h.consume(.05)-.02)<1e-10);h.request(99,3);assert.ok(h.remaining<=.1);assert.ok(h.credit>=0);h.clear();assert.equal(h.active,false);
});
test('sparks, trails and rings share one enforced 500-record ceiling',()=>{
  const scene=new Scene(),manager=new ParticleManager({scene,capacity:500}),rings=new ShockwaveRings(manager);
  for(let i=0;i<800;i++)manager.emit({kind:'trail',priority:0,life:1});assert.equal(manager.counts.trail,128);
  for(let i=0;i<800;i++)rings.spawn({priority:3,life:1});assert.equal(manager.counts.ring,12);
  for(let i=0;i<1000;i++){manager.emit({kind:'spark',priority:3,life:1});assert.ok(manager.counts.total<=500);assert.equal(manager.counts.total,manager.pool.activeCount);assert.equal(manager.rings.activeCount,manager.counts.ring);}
  assert.equal(manager.counts.total,500);manager.update(2);assert.equal(manager.counts.total,0);assert.equal(manager.rings.activeCount,0);
  const trails=new MotionTrails({manager,sourceCapacity:1}),source={id:0,active:true,generation:1,x:0,y:0,palette:0};trails.update([source]);source.y=1;trails.update([source]);const before=manager.counts.trail;source.generation++;source.y=8;trails.update([source]);assert.equal(manager.counts.trail,before);
  manager.dispose();assert.equal(scene.children.length,0);assert.throws(()=>new ParticleManager({scene,capacity:501}),RangeError);
});

