    this.text.resize(rect);
  }
  reset() {
    this.requests.clear();
    this.particles.clear();
    this.trails.reset();
    this.text.clear();
    this.shake.reset();
    this.hitStop.clear();
    this.lightLife.fill(0);
    for (const light of this.impactLights) light.intensity = 0;
  }
  dispose() {
    this.reset();
    this.text.dispose();
    this.particles.dispose();
  }
}
