}
.eyebrow {
  font: 8px monospace;
  letter-spacing: 0.16em;
  color: #70c1cf;
  display: flex;
  align-items: center;
  gap: 8px;
}
.eyebrow > span {
  width: 18px;
  height: 1px;
  background: #70c1cf;
}
h1 {
  position: relative;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 77px;
  letter-spacing: -0.055em;
  font-weight: 900;
  line-height: 0.86;
  margin: 26px 0 18px;
  color: #e4f0f7;
}
h1 em {
  font-style: normal;
  color: #73e4e9;
}
h1 .title-cross {
  position: absolute;
  font: 200 75px Arial;
  right: 7px;
  top: 21px;
  color: #315b70;
  transform: rotate(0);
}
.tagline {
  font: 10px monospace;
  letter-spacing: 0.21em;
  color: #b4c8d5;
  margin: 22px 0 12px;
}
.intro {
  font-size: 12px;
  line-height: 1.8;
  color: #829eb3;
  margin-bottom: 22px;
}
.threat-guide {
  display: flex;
  gap: 17px;
  align-items: center;
  padding: 16px 0;
  border-top: 1px solid #7dabc31c;
  border-bottom: 1px solid #7dabc31c;
  margin-bottom: 22px;
  color: #859ead;
  font: 8px monospace;
}
.threat-guide > span {
  display: flex;
  align-items: center;
  gap: 6px;
}
.species {
  display: inline-block;
  width: 12px;
  height: 8px;
  background: #71bfaa;
  clip-path: polygon(
    15% 0,
    85% 0,
    100% 30%,
    100% 70%,
    85% 70%,
    85% 100%,
    60% 100%,
    60% 70%,
    40% 70%,
    40% 100%,
    15% 100%,
    15% 70%,
    0 70%,
    0 30%
  );
}
.species.squid {
  background: #b199e2;
}
.species.scout {
  background: #eb7a99;
}
.threat-guide .bonus {
  color: #cdb480;
  margin-left: auto;
}
.start-button {
  height: 53px;
  width: 100%;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font: 700 10px monospace;
  letter-spacing: 0.1em;
}
.start-button b {
  font-size: 18px;
  margin-left: 12px;
}
.start-button kbd {
  color: #247984;
  border-color: #20777d3a;
}
.title-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
}
.title-bottom button {
  padding: 10px 0;
  font-size: 10px;
}
.title-bottom > span {
  font: 7px monospace;
  color: #4d7486;
  letter-spacing: 0.1em;
}
.title-bottom .live-dot {
  width: 3px;
  height: 3px;
  margin-right: 4px;
}
.small-panel h2,
.settings-panel h2,
.result-panel h2 {
  font-size: 29px;
  font-weight: 600;
  letter-spacing: -0.04em;
  margin: 18px 0 12px;
}
.small-panel p,
.result-panel p {
  font-size: 12px;
  line-height: 1.7;
  color: #819db1;
  margin-bottom: 25px;
}
.wide {
  width: 100%;
  padding: 15px 17px;
  margin-top: 9px;
  text-align: left;
  font: 10px monospace;
  letter-spacing: 0.07em;
}
.wide > span {
  float: right;
}
.settings-panel {
  padding: 28px 34px;
}
.settings-panel label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 35px;
  color: #9eb5c7;
  font-size: 11px;
  gap: 20px;
}
.settings-panel input[type="range"] {
  width: 140px;
  accent-color: var(--cyan);
}
.settings-panel input[type="checkbox"] {
  accent-color: var(--cyan);
}
.settings-panel select {
  background: #122337;
  color: #b5d4e3;
  border: 1px solid var(--border);
  padding: 5px 8px;
  border-radius: 3px;
  font-size: 11px;
}
.control-reference {
  padding: 16px 0;
  margin-top: 8px;
  border-top: 1px solid var(--border);
  display: grid;
  grid-template-columns: 95px 1fr;
  gap: 11px;
  color: #6d8ea3;
  font: 9px/1.8 monospace;
}
.control-reference b {
  color: #9ec0cf;
  font-size: 8px;
  letter-spacing: 0.08em;
}
.result-score {
  margin: 26px 0 20px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--border);
}
.result-score strong {
  font: 48px monospace;
  letter-spacing: 0.06em;
  color: #93f2f2;
}
.result-score small {
  display: block;
  font: 8px monospace;
  color: #78a5b7;
  letter-spacing: 0.15em;
  margin-top: 10px;
}
.result-stats {
  display: flex;
  gap: 28px;
  margin-bottom: 22px;
}
.result-stats span {
  font: 7px monospace;
  color: #617e94;
  display: block;
  letter-spacing: 0.09em;
  margin-bottom: 9px;
}
.result-stats b {
  font: 15px monospace;
  color: #b4cdd9;
}
.transition-message {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  pointer-events: none;
  background: radial-gradient(ellipse, #05091455, transparent 60%);
}
.transition-message small {
  font: 10px monospace;
  letter-spacing: 0.3em;
  color: #79d5df;
  margin-bottom: 20px;
}
.transition-message strong {
  font: 700 44px Arial;
  letter-spacing: -0.025em;
  color: #cef7ff;
  text-shadow: 0 0 30px #44b4d380;
}
.transition-message span {
  font: 9px monospace;
  color: #7cacbe;
  letter-spacing: 0.16em;
  margin-top: 18px;
}
.footer {
  height: 48px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 44px;
  color: #547083;
  font: 8px monospace;
  letter-spacing: 0.05em;
  border-top: 1px solid #50779118;
}
.footer > span {
  display: flex;
  align-items: center;
  gap: 6px;
}
kbd {
  font: 8px monospace;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 18px;
  padding: 0 5px;
  border: 1px solid #64809240;
  border-radius: 3px;
  color: #90adbd;
}
.footer i {
  display: inline-block;
  height: 8px;
  width: 1px;
  background: #234050;
  margin: 0 8px;
}
.footer-right b {
  font-weight: 400;
  color: #38576d;
  margin-left: 3px;
}
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.touch-controls {
  display: none;
  justify-content: center;
  gap: 20px;
  padding: 8px;
  flex-shrink: 0;
}
.touch-controls button {
  min-width: 80px;
  height: 40px;
  touch-action: none;
  user-select: none;
}
.game-shell[data-touch="true"] .touch-controls {
  display: flex;
}
@media (max-height: 800px) and (min-width: 700px) {
  .topbar {
    height: 76px;
  }
  .mission-strip {
    height: 36px;
  }
  .footer {
    height: 36px;
  }
  .title-panel {
    padding: 24px 34px 16px;
    width: 480px;
  }
  h1 {
    font-size: 67px;
    margin-top: 22px;
  }
  .intro {
    margin-bottom: 15px;
  }
  .threat-guide {
    padding: 12px 0;
    margin-bottom: 18px;
  }
  .title-panel .tagline {
    margin-top: 18px;
  }
  .settings-panel {
    padding: 22px 30px;
  }
  .settings-panel label {
    min-height: 29px;
  }
}
@media (max-width: 850px) {
  .topbar {
    padding: 0 24px;
  }
  .top-actions .online {
    display: none;
  }
  .score-cluster {
    gap: 20px;
  }
  .brand small {
    display: none;
  }
  .mission-strip,
  .footer {
    padding-left: 24px;
    padding-right: 24px;
  }
  .top-left,
  .field-bottom {
    left: 24px;
  }
  .top-right,
  .field-bottom {
    right: 24px;
  }
  .footer-right {
    display: none !important;
  }
}
@media (max-width: 600px) {
  .topbar {
    height: 73px;
    padding: 0 16px;
  }
  .brand {
    gap: 7px;
  }
  .brand-mark {
    font-size: 26px;
  }
  .brand strong {
    font-size: 9px;
    letter-spacing: 0.08em;
  }
  .best-readout {
    display: none;
  }
  .score-cluster b {
    font-size: 19px;
  }
  .score-cluster span {
    font-size: 7px;
  }
  .top-actions {
    gap: 5px;
  }
  .icon-button {
    width: 28px;
    height: 28px;
  }
  .mission-strip {
    padding: 0 16px;
    height: 39px;
    font-size: 7px;
  }
  .mission-strip #objective {
    display: none;
  }
  .divider {
    display: none;
  }
  .lives {
    gap: 6px;
  }
  .wave-count {
    margin-left: 9px;
  }
  .field-corner {
    top: 7px;
    font-size: 6px;
  }
  .top-left {
    left: 14px;
  }
  .top-right {
    right: 14px;
  }
  .field-bottom {
    font-size: 6px;
    left: 14px;
    right: 14px;
    bottom: 8px;
  }
  .glass-panel {
    width: 100%;
    max-width: 420px;
    padding: 25px;
  }
  .modal-layer {
    padding: 14px;
  }
  .title-panel h1 {
    font-size: 66px;
    margin-top: 24px;
  }
  .intro {
    font-size: 11px;
  }
  .threat-guide {
    gap: 12px;
    font-size: 7px;
  }
  .threat-guide .bonus {
    font-size: 6px;
  }
  .title-bottom > span {
    font-size: 6px;
  }
  .footer {
    height: 34px;
    justify-content: center;
    padding: 0 6px;
    font-size: 7px;
  }
  .settings-panel {
    max-height: 100%;
    overflow: auto;
  }
  .control-reference {
    grid-template-columns: 80px 1fr;
    font-size: 8px;
  }
  .result-stats {
    gap: 20px;
  }
  .transition-message strong {
    font-size: 32px;
  }
  .stage {
    min-height: 210px;
  }
}
@media (max-height: 650px) {
  .title-panel h1 {
    font-size: 48px;
    margin: 18px 0 12px;
  }
  .title-panel .intro {
    margin: 10px 0;
  }
  .title-panel .tagline {
    margin: 12px 0 8px;
  }
  .threat-guide {
    padding: 10px 0;
    margin-bottom: 12px;
  }
  .title-panel {
    padding-top: 20px;
  }
  .title-bottom {
    margin-top: 7px;
  }
  .title-bottom > span {
    display: none;
  }
  .start-button {
    height: 43px;
  }
  .field-corner {
    display: none;
  }
  .settings-panel {
    max-height: 100%;
    overflow: auto;
  }
}

