import { Gameplay } from '../src/Space_Invaders/Gameplay.js';
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
export function decide(d){
  const p=d.player,aliens=d.aliens,bullets=d.enemyShots,f=d.formation;
  if(!aliens.length)return 0;
  let target=p.x,best=Infinity;
  const speed=f.dropping?0:f.direction*.48/f.interval;
  let left=Infinity,right=-Infinity;
  for(const a of aliens){left=Math.min(left,a.x-.73);right=Math.max(right,a.x+.73);}
  for(const a of aliens){
    const t=(a.y-p.y-.9)/30;
    let shift=speed*t;
    if(shift>0&&right+shift>15.5)shift=2*(15.5-right)-shift;
    if(shift<0&&left+shift< -15.5)shift=2*(-15.5-left)-shift;
    const aim=clamp(a.x+shift,-14.5,14.5);
    let cost=Math.abs(aim-p.x)*.7+(a.y+10)*.14;
    for(const b of bullets){const hit=(p.y-b.y)/b.vy;if(hit>0&&hit<1.2&&Math.abs(b.x+b.vx*hit-aim)<1.2)cost+=15*(1.2-hit);}
    if(cost<best){best=cost;target=aim;}
  }
  let bestAction=0,bestCost=Infinity;
  for(const action of [-1,0,1]){
    let x=p.x,v=p.vx,cost=0;
    for(let step=1;step<=36;step++){
      const dt=1/60,t=step*dt,desired=action*16,acc=!desired||Math.sign(desired)!==Math.sign(v)?140:100;
      v+=clamp(desired-v,-acc*dt,acc*dt);x=clamp(x+v*dt,-14.7,14.7);
      if(step===10)cost+=Math.abs(x-target)*1.5;
      for(const b of bullets){const by=b.y+b.vy*t,bx=b.x+b.vx*t;if(Math.abs(by-p.y)<.8&&Math.abs(bx-x)<1.0)cost+=1000;}
    }
    cost+=Math.abs(x-target)*.35+Math.abs(action)*.015;
    if(cost<bestCost){bestCost=cost;bestAction=action;}
  }
  return bestAction;
}
function snap(g){
  const records=pool=>Array.from(pool.activeIds.slice(0,pool.activeCount),id=>pool.items[id]);
  return {player:g.entities.player.items[0],aliens:records(g.entities.aliens),enemyShots:records(g.entities.enemyShots),formation:g.formation};
}
if(process.argv[1]?.endsWith('simulate.mjs')){
  for(const seed of [42,123,777]){
    const g=new Gameplay();g.reset(seed);let input={moveX:0,fire:true};
    for(let i=0;i<120*500;i++){
      if(i%6===0)input.moveX=decide(snap(g));g.step(1/120,input);
      if(g.state.phase==='VICTORY'||g.state.phase==='GAME_OVER')break;
    }
    console.log(seed,g.state);
  }
}

